// Middleware de limitation par seau a jetons, en memoire, pour l'exemple.
// En production on stocke les compteurs dans un cache partage (ex. Redis).
const seaux = new Map() // cle -> { jetons, dernierRemplissage }

const CAPACITE = 10        // 10 jetons maximum dans le seau
const DEBIT = 2            // 2 jetons ajoutes par seconde

function limiterDebit(req, res, next) {
  // On limite par utilisateur si connecte, sinon par adresse IP
  const cle = req.user?.id ?? req.ip
  const maintenant = Date.now()
  const seau = seaux.get(cle) ?? { jetons: CAPACITE, dernierRemplissage: maintenant }

  // On recharge le seau selon le temps ecoule
  const secondesEcoulees = (maintenant - seau.dernierRemplissage) / 1000
  seau.jetons = Math.min(CAPACITE, seau.jetons + secondesEcoulees * DEBIT)
  seau.dernierRemplissage = maintenant

  if (seau.jetons < 1) {
    // Plus de jeton : on refuse avec 429 et on indique quand reessayer
    res.set('Retry-After', '1')
    return res.status(429).json({ error: 'Trop de requetes, reessayez plus tard' })
  }

  seau.jetons -= 1 // la requete consomme un jeton
  seaux.set(cle, seau)
  next()
}

